void AnalogFace::draw(uint8_t hour, uint8_t minute, GxEPD2_BW<GxEPD2_154_D67, GxEPD2_154_D67::HEIGHT>& display){
    int16_t X, Y;
    X = display.width()/2;
    Y = display.height()/2;

    display.drawBitmap(0, 0, antique_background, 200, 200, GxEPD_BLACK, GxEPD_WHITE);

    uint16_t minutenprozent = (minute/60)*100;
    uint16_t hourAngle = ((360 * (hour%12)) / 12) + (minute* 0.5);
    uint16_t minuteAngle = ((360 * minute) / 60);
    
    drawHand(X, Y, hourAngle, 36, display);
    drawHand(X+1, Y, hourAngle, 36, display);
    drawHand(X, Y+1, hourAngle, 36, display);

    drawHand(X, Y, minuteAngle, 66, display);
};

void AnalogFace::drawHand(int centerX, int centerY, uint16_t angle, int length, GxEPD2_BW<GxEPD2_154_D67, GxEPD2_154_D67::HEIGHT>& display)
{
    float adjustedAngle = 90 - angle;
    float rad = adjustedAngle * (PI / 180);
    int x = centerX + cos(rad) * length;
    int y = centerY - sin(rad) * length;
    display.drawLine(centerX, centerY, x, y, GxEPD_BLACK);
}
